// 55 AA <addr> FF 00 00 <sum & 0xFF>
const address = 1;
const frame = [0x55, 0xAA, address, 0xFF, 0x00, 0x00];
frame.push(frame.reduce((a, b) => a + b, 0) & 0xFF);
msg.payload = Buffer.from(frame);
node.status({ text: 'TX ' + msg.payload.toString('hex').match(/../g).join(' ') });
return msg;

const b = msg.payload;
msg.payload = Buffer.isBuffer(b) ? b.length + ' bytes: ' + b.toString('hex').match(/../g).join(' ') : String(b);
return msg;

let b = msg.payload;
if (!Buffer.isBuffer(b) || b.length === 0) {
  node.status({ fill: 'red', shape: 'ring', text: 'no reply' });
  return null;
}
const start = b.indexOf(Buffer.from([0xEB, 0x90]));
if (start < 0) {
  node.status({ fill: 'red', shape: 'ring', text: 'no EB 90 header, ' + b.length + ' bytes' });
  return null;
}
b = b.slice(start);
if (b.length < 74) {
  node.status({ fill: 'yellow', shape: 'ring', text: 'short reply: ' + b.length + ' bytes' });
  return null;
}
let sum = 0;
for (let i = 0; i < 73; i++) sum += b[i];
if ((sum & 0xFF) !== b[73]) {
  node.status({ fill: 'red', shape: 'ring', text: 'bad checksum' });
  return null;
}
const count = (b[22] >= 1 && b[22] <= 24) ? b[22] : Math.min(Math.max(b[8], 1), 24);
const cells = [];
for (let i = 0; i < count; i++) cells.push(b.readUInt16BE(23 + 2 * i));
msg.payload = {
  address: b[2],
  voltage_V: b.readUInt16BE(4) / 100,
  cell_avg_mV: b.readUInt16BE(6),
  cells_detected: b[8],
  cell_highest: b[9],
  cell_lowest: b[10],
  balancing: (b[11] & 1) ? 'charging cell' : (b[11] & 2) ? 'discharging cell' : 'idle',
  alarms: { cell_count_error: !!(b[12] & 1), wire_resistance_high: !!(b[12] & 2), overvoltage: !!(b[12] & 4) },
  delta_mV: b.readUInt16BE(13),
  balance_current_mA: b.readUInt16BE(15),
  trigger_mV: b.readUInt16BE(17),
  max_balance_current_mA: b.readUInt16BE(19),
  balancing_switch: b[21] === 1,
  cells_configured: b[22],
  cells_mV: cells,
  temperature_C: b.readInt16BE(71)
};
node.status({ fill: 'green', shape: 'dot', text: msg.payload.voltage_V + ' V, ' + count + ' cells' });
return msg;
